def adder_ripple_gidney_mod(a_reg, b_reg):
    n = len(a_reg)
    n = len(b_reg)
    'Apply a modular Gidney ripple-carry adder.\n\n    This circuit performs in-place modular addition of a_reg into b_reg:\n\n    ``|a>|b> -> |a>|a + b mod 2^n>``\n\n    The circuit has linear depth and requires n - 1 ancilla qubits.\n\n    Reference:\n    Gidney, C. (2018). Halving the cost of quantum addition. Quantum, 2, 74.\n\n    Args:\n        a_reg (array[qubit, n]): The addend register.\n        b_reg (array[qubit, n]): The target register.\n            Modified in-place: b_reg += a_reg mod 2^n.\n\n    '
    anc = qarray(comptime(n - 1))
    temp_and_compute(a_reg[0], b_reg[0], anc[0])
    if n == 1:
        cx(anc[0], b_reg[0])
    else:
        if n > 2:
            for i in range(n - 2):
                _g_majority_gate(a_reg[i + 1], b_reg[i + 1], anc[i], anc[i + 1])
        cx(a_reg[n - 1], b_reg[n - 1])
        cx(anc[n - 2], b_reg[n - 1])
        if n > 2:
            for i in range(n - 2):
                _g_unmajority_gate(a_reg[n - 2 - i], b_reg[n - 2 - i], anc[n - 3 - i], anc[n - 2 - i])
    temp_and_uncompute(a_reg[0], b_reg[0], anc[0])
    cx(a_reg[0], b_reg[0])
    discard_array(anc)

