def ccx_v_chain(controls_a, controls_b, target):
    n = len(controls_a)
    n = len(controls_b)
    'Apply the CCX V chain in linear depth with 2n - 1 Toffoli gates.\n\n    Args:\n        controls_a (array[qubit, n]): Chain register, restored at the end.\n        controls_b (array[qubit, n]): Second control of each Toffoli.\n        target (qubit): Qubit flipped by the middle Toffoli.\n\n    '
    if n == 0:
        return
    for i in range(n - 1):
        toffoli(controls_a[i], controls_b[i], controls_a[i + 1])
    toffoli(controls_a[n - 1], controls_b[n - 1], target)
    if n >= 2:
        for i in range(n - 2, -1, -1):
            toffoli(controls_a[i], controls_b[i], controls_a[i + 1])

